  '叠加过滤（多条件为「且」关系，硬过滤）': 'Overlay filter (multiple conditions are combined with AND, hard filter)',
  '叠加条件直接过滤策略候选，策略 / 回测 / 监控一致生效；只影响新入场，不触发已持仓卖出；字段可点「最新」切换为「前N日」（按交易日回看，上限 60 日，与信号库同口径）；字段数据缺失的日期不入选（如扩展数据未回补的交易日）。': 'Overlay conditions filter strategy candidates directly and apply consistently across strategy / backtest / monitoring; they only affect new entries and never trigger sells on existing positions; click a field\'s "Latest" to switch it to "Prev N days" (looked back by trading day, up to 60 days, same as the signal library); days where the field data is missing are excluded (e.g. trading days without backfilled extension data).',
  ' matrix 策略不支持字符串字段条件。': ' matrix strategies do not support string field conditions.',
  '当前策略类型不支持叠加条件（composite 请对子策略单独配置，分钟策略不支持）。': 'This strategy type does not support overlay conditions (configure composite sub-strategies individually; minute strategies are not supported).',
  '对通过筛选的候选按因子加权打分排序；评分不改变是否入选，只决定排序先后。权重保存时自动归一。': 'Candidates that pass the filter are scored and ranked by weighted factors; the score does not change selection, only the ordering. Weights are normalized automatically when saved.',
  '{n} 个因子': '{n} factors',
  '控制买卖时点：出入场触发器对回测与监控生效（任一命中即触发）；策略扫描不消费触发器，仍按策略自身规则。风控与持仓纪律作为策略默认值保存，回测 / 优化 / 走查打开时自动继承。': 'Controls when trades happen: entry/exit triggers apply to backtests and monitoring (any match fires); strategy scans do not consume triggers and still follow the strategy\'s own rules. Risk controls and holding discipline are saved as strategy defaults and inherited when backtests / optimizations / walk-forwards open.',
  '风控与持仓纪律': 'Risk & Holding Discipline',
