  '夏普比率 (Sharpe Ratio)': 'Sharpe Ratio',
  '收益序列的平均收益 ÷ 总波动，并按 252 期年化。': 'Average return of the return series ÷ total volatility, annualized over 252 periods.',
  '数值越高，单位波动获得的收益越多；小样本时仅供参考。': 'The higher the value, the more return per unit of volatility; treat small samples as indicative only.',
  '索提诺比率 (Sortino Ratio)': 'Sortino Ratio',
  '收益序列的平均收益 ÷ 下行偏差，并按 252 期年化。': 'Average return of the return series ÷ downside deviation, annualized over 252 periods.',
  '只惩罚负收益波动，不将向上波动视为风险。': 'Penalizes only negative-return volatility; upside volatility is not treated as risk.',
  '回测权益从历史高点到随后最低点的最大跌幅。': 'The largest drop from a peak in backtest equity to the following low.',
  '越接近 0 通常代表历史资金回撤越小。': 'The closer to 0, the smaller the historical drawdown of capital.',
  '蒙卡回撤 (中位/95%)': 'Monte Carlo Drawdown (Median / 95%)',
  '对交易收益有放回重抽样 1000 次, 各算最大回撤: 中位值 = 典型运气下的回撤, 95% 边界 = 偏悲观的压力边界。': 'Resamples trade returns with replacement 1000 times and computes the max drawdown each time: the median is the drawdown under typical luck, while the 95% bound is a pessimistic stress bound.',
  '中位值用于和实际最大回撤对照判断序列运气; 资金管理按 95% 边界准备。交易数多时两者可能同时逼近 -100%, 参考价值下降。': 'Compare the median with the actual max drawdown to judge the luck of the sequence, and size capital against the 95% bound. With many trades both can approach -100%, reducing their usefulness.',
