  '对比盈利单与亏损单入场时的因子取值：胜单均值明显高于败单 → 该因子在本轮交易里贡献了正筛选力；反之在拖后腿。原始因子量纲不同，只看相对差异。': 'Compares the factor values at entry between winning and losing trades: a clearly higher mean for winners means the factor added positive screening power in this round, and the opposite means it dragged performance down. The factors have different units, so only relative differences matter.',
