  '回测基于历史数据与当前参数设定模拟,受成交假设与市场环境影响,过往结果不代表未来收益; 行情数据来自第三方数据源,其准确性、完整性与及时性不作保证,可能存在缺失、延迟或错误; 仅供参考,不构成投资建议,请独立决策并自担风险。': 'The backtest simulates past data under the current parameter settings; results depend on fill assumptions and market conditions, and past results do not represent future returns. Market data comes from third-party sources whose accuracy, completeness and timeliness are not guaranteed and may contain gaps, delays or errors. It is for reference only and is not investment advice — make your own decisions and bear the risk.',
