  '决定哪些股票进入候选：基础过滤 → 策略参数 → 叠加条件，逐层收紧；此处改动只影响本次回测，不会保存。': 'Decides which stocks become candidates: base filters → strategy parameters → overlay conditions, tightening layer by layer; changes here affect this backtest only and are not saved.',
