  '例如最小值 71 表示只把评分 ≥ 71 的股票放入下一交易日买入预选池。': 'For example, a minimum of 71 puts only stocks scored ≥ 71 into the buy shortlist for the next trading day.',
  '触发 / 成交 / 仓位关系': 'Trigger / Fill / Position Relationships',
  '触发器决定什么时候产生买卖信号；评分只在多个买点同时出现时排序。': 'Triggers decide when a buy or sell signal appears; the score only ranks them when several entry points occur at once.',
  '成交口径可分别设置建仓/清仓：默认建仓次日开盘（避免未来函数）、清仓当日收盘（持仓中可盘中/收盘卖）。': 'Entry and exit fills can be set separately: entry defaults to the next day\'s open (to avoid look-ahead bias) and exit to the same day\'s close (positions can be sold intraday or at the close).',
  '退出优先级：止损/移动止损 &gt; 卖点信号 &gt; 到期平仓；到期只作兜底，不抢占卖点或风控。': 'Exit priority: stop loss / trailing stop &gt; exit signal &gt; expiry close; expiry is only a fallback and never preempts an exit signal or risk control.',
  '最大持仓数控制同时持股数量，最大总仓位控制资金投入比例；剩余现金不等于可新增持仓名额。': 'Max positions controls how many stocks are held at once, max total position controls how much capital is deployed; spare cash is not an extra slot.',
  '当前为 Matrix 策略，进出场信号由策略公式生成，不能用列信号覆盖。': 'This is a Matrix strategy: entry and exit signals come from the strategy formula and cannot be overridden with column signals.',
