  'ETF 仅技术类策略,读 ETF enriched': 'ETF supports technical strategies only; reads ETF enriched data',
  '需要单票调试或自选池回测时再限定股票池；默认由基础过滤、策略条件与买卖触发器在全市场筛选。': 'Restrict the stock pool only for single-symbol debugging or watchlist backtests; by default base filters, strategy conditions and buy/sell triggers screen the whole market.',
