  '策略回测复用策略定义 ( 买入/卖出触发器、止损、最大持仓 ) 做全周期模拟。服务器建议优先使用最近3个月；长周期建议本机或 8GB 以上内存环境运行。': 'The strategy backtest reuses the strategy definition (buy/sell triggers, stop loss, max positions) for a full-period simulation. On the server prefer the most recent 3 months; for longer periods run it locally or on a machine with 8GB+ of memory.',
