  '三步看懂本页：': 'Understand this page in three steps:',
  '① 因子 = 给股票打分排序的特征（如 20日涨幅、换手率变化）；② 本页度量过去哪些特征与次日涨跌存在稳定关联；③ IC = 关联强度（绝对值越大越强，负值反向用），IR = 稳定度（越大越稳）。所有结果均为历史统计，不构成投资建议，不代表未来表现。': '① A factor is a feature that scores and ranks stocks (e.g. 20-day return, turnover change); ② this page measures which features had a stable relation to the next day\'s move; ③ IC = relation strength (the larger the absolute value the stronger; negative values are used in reverse), IR = stability (larger is steadier). All results are historical statistics, are not investment advice and do not represent future performance.',
