  'IC 均值': 'Mean IC',
  '每天用因子给股票打分、与次日真实涨跌算相关性（Rank IC）的均值。|IC|≥0.02 且稳定即视为历史有效；负值同样有效（反向使用）。': 'The mean of the daily Rank IC between the factor\'s score and the next day\'s actual move. |IC|≥0.02 with stability counts as historically valid; negative values are valid too (used in reverse).',
