  'IC 均值 ÷ IC 波动。≥0.3 值得关注，≥0.5 相当稳定。': 'Mean IC ÷ IC volatility. ≥0.3 is worth watching, ≥0.5 is quite stable.',
  't 值(NW)': 't-value (NW)',
  'Newey-West HAC 稳健 t 值（滞后 1）：|t|≥2 视为统计显著；悬停查看多重检验校正后的 q 值（≤0.1 通过）。样本不足显示 —。': 'Robust Newey-West HAC t-value (lag 1): |t|≥2 counts as statistically significant; hover to see the multiple-testing adjusted q-value (≤0.1 passes). Shows — when the sample is too small.',
  '方向一致占比': 'Direction hit rate',
  'IC 与自身方向一致的天数占比。50% 是抛硬币，55%+ 不错。': 'Share of days where the IC sign matches the factor\'s own direction. 50% is a coin flip, 55%+ is decent.',
  '多空收益': 'Long-short return',
  '每期买因子最高组、（模拟）卖最低组的累计收益差。A 股做空受限，此列为理论口径。': 'The cumulative return difference between buying the top factor group and (simulated) selling the bottom group each period. Shorting is restricted in A-shares, so this column is theoretical.',
