  '不知道选什么因子？让系统全量筛选达标因子并自动搜索组合（嵌套样本外验证）': 'Not sure which factors to pick? Let the system screen every factor and search combinations automatically (nested out-of-sample validation)',
  '左侧选因子（或用预设）→ 点「筛选」批量检验 → 点击结果行看单因子详情。 IC 衡量历史上因子值与后续涨跌的关联强度（绝对值越大关联越强），IR 是稳定度。': 'Pick factors on the left (or use a preset) → click “Screen” for a batch test → click a result row for the single-factor detail. IC measures how strongly the factor value relates to the following move (the larger the absolute value, the stronger the relation); IR is the stability.',
