  '不用挑因子：先全量统计筛选（|t|≥2、q≤0.1、IC/IR 达标），再用达标池做相关性去重 → 组合搜索 → 嵌套样本外验证。结果里能看到哪些因子/组合达标、不达标的差在哪。': 'No need to pick factors by hand: first run the full statistical screen (|t|≥2, q≤0.1, IC/IR qualified), then deduplicate the qualified pool by correlation → combination search → nested out-of-sample validation. The results show which factors and combinations qualify and what the failures are missing.',
