  '配置后同一代码允许一天多行, 按代码+时间列去重; 填 __pull_ts__ 时自动注入每次拉取的时刻, 盘中多次拉取各存一盘': 'Once configured the same symbol may have several rows per day, deduplicated by symbol + time column; with __pull_ts__ the moment of each pull is injected automatically, so intraday pulls each keep their own session',
  '列表迷你图列与序列接口按此口径取数; 自动判断依据时间列数据形态': 'The list sparkline column and the series API use this rule; it is inferred from the shape of the time column',
