  '日期参数值的序列化格式; 时间戳 = 该交易日北京时间 00:00:00': 'How the date parameter value is serialized; a timestamp means 00:00:00 Beijing time on that trading day',
  'since · 留空=每次全量': 'since · blank = full pull every time',
  '每次拉取自动带上本地已有最大时间值 (?参数=值), 源只返回其后数据; 缺多少补多少, 本地无数据时自动整日全量。需先配置时间字段; 两级拉取不适用': 'Every pull automatically carries the largest timestamp already stored locally (?param=value) and the source only returns data after it; missing ranges are filled in, and with no local data the whole day is pulled. Configure the time field first; not applicable to two-level pulls',
