  '开启后,每个交易日到点自动生成大盘复盘报告并归档,静默执行。 下次打开本页即可在历史列表看到新报告;也可选推送到飞书。': 'Once enabled, a market review report is generated and archived automatically at the set time on every trading day, running silently. Open this page again to see the new report under “History”; you can also push it to Feishu.',
