  '竞价数据源未配置': 'Auction data source not configured',
  '竞价异动 (同花顺盘前风向标与全市场竞价扫描) 依赖 fuyao 数据源, 复盘页的龙虎榜同样来自该数据源。在「设置 → 数据源」配置 fuyao API Key 后即可使用。': 'Auction moves (the THS pre-market wind vane and the full-market auction scan) rely on the fuyao data source; the leaderboard on the review page comes from the same source. Configure a fuyao API key under Settings → Data Sources to enable them.',
  '前往配置数据源': 'Go configure data source',
  '全市场竞价扫描': 'Full-Market Auction Scan',
  '待采集任务启用': 'Enable the collection task',
  '9:25 竞价终态后扫描全市场 (实测 5547 只约 2 秒), 自动筛出高开 ≥5% 且竞价量比 ≥10 的标的并按日落盘积累历史。竞价明细无历史接口, 数据从采集启用之日起积累。': 'After the auction settles at 9:25 the whole market is scanned (about 5,547 stocks in roughly 2 seconds); stocks opening ≥5% with an auction volume ratio ≥10 are filtered automatically and stored daily to build history. The auction detail feed has no history API, so data accumulates only from the day collection is enabled.',
  '风向标为同花顺盘前竞价筛选名单 (每日约 5~6 只)。60 日回测: 名单当日开盘买入均值 +0.54% (超额 +0.44%), 但高开 ≥5% 子集当日 -1.97% — 追高是陷阱, 次日无显著优势, 仅作当日观察。': 'The wind vane is the THS pre-market auction screen (about 5-6 stocks a day). 60-day backtest: buying the list at the open the same day averaged +0.54% (excess +0.44%), but the >=5% gap-up subset was -1.97% that day - chasing highs is a trap with no clear edge the next day, so treat it as an intraday observation only.',
  '盘前风向标暂不可用': 'Pre-market wind vane is unavailable',
