  '盘中信号加载失败，请检查数据源与网络': 'Failed to load intraday signals. Check the data source and network.',
  '当前筛选下没有命中标的': 'No stocks match the current filter',
  '暂无数据': 'No data',
  '口径说明: 偏离值 = 个股 N 日累计涨跌幅 − 对应指数同期涨跌幅 (沪主板: 上证A指/上证指数, 科创板: 科创50, 深主板: 深证A指/深证成指, 创业板: 创业板综指, 北: 北证50)。 阈值为交易所异常波动披露标准的近似值, 仅供风险提示, 不构成监管认定。每只股票在 3日/10日/30日 三档各算一个接近度 (|偏离值| ÷ 该档阈值, 阈值随板块不同; 2026-07-06 起主板风险警示股票与普通股票同口径), 表格「接近度」列与状态取三档中的最高值, 来源窗口的偏离值颜色加重显示、其余窗口淡化; ≥100% 已触发、≥70% 边缘、≥50% 观察。 偏离列亦可在自选/策略的「异动」列组中启用, 并可作为监控规则与自定义信号的阈值字段。': 'Criteria: deviation = stock N-day cumulative move - the matching index\'s move over the same period (Shanghai main board: SSE A Index / SSE Composite, STAR Market: STAR 50, Shenzhen main board: SZSE A Index / SZSE Component, ChiNext: ChiNext Composite, BSE: BSE 50). The thresholds approximate the exchange disclosure standards for abnormal moves and serve risk warnings only - they are not regulatory findings. Each stock gets a proximity score for each of the 3-day / 10-day / 30-day tiers (|deviation| / that tier\'s threshold; the threshold varies by board; from 2026-07-06 main-board risk-warning stocks use the same criteria as ordinary stocks). The table\'s "Proximity" column and status take the highest of the three tiers; the source tier\'s deviation is highlighted while the others are dimmed; >=100% triggered, >=70% edge, >=50% watch. The deviation column can also be enabled in the "Abnormal Move" column group of Watchlist / Strategy and used as a threshold field for monitoring rules and custom signals.',
  '监控未开启': 'Monitoring is off',
  '开启后按交易所异动规则实时计算全市场个股的涨跌幅偏离值 (个股 N 日累计涨跌 − 对应指数同期), 找出接近触发「异常波动 / 严重异常波动」的标的。 计算量较大, 默认关闭; 每次计算的结果会保留, 关闭后仍可查看 (不再实时更新)。': 'Once enabled, the price-move deviation of every stock in the market is computed in real time following the exchange abnormality rules (stock N-day cumulative move - the same period for the matching index), to surface names close to triggering an abnormal or severely abnormal move. The computation is heavy, so it is off by default; each run is kept, and you can still review the last result after switching it off (no longer updating live).',
  '需要告警推送时, 在': 'To push alerts, create a rule in',
  '新建「异动监控」规则 —— 后台持续评估, 触发时统一走触发记录 / 站内通知 / 外部渠道推送, 与本页开关互不影响。': 'Create an "Abnormal Move Monitor" rule - it is evaluated continuously in the background, and a trigger always goes through trigger records / in-app notifications / external channels, independently of this page switch.',
