  '叠加过滤（多条件为「且」关系，硬过滤）': '追加フィルタ (複数条件は AND 結合のハードフィルタ)',
  '叠加条件直接过滤策略候选，策略 / 回测 / 监控一致生效；只影响新入场，不触发已持仓卖出；字段可点「最新」切换为「前N日」（按交易日回看，上限 60 日，与信号库同口径）；字段数据缺失的日期不入选（如扩展数据未回补的交易日）。': '追加条件は戦略候補を直接絞り込み、戦略 / バックテスト / 監視で同じ挙動になります。新規エントリーのみに影響し、保有ポジションの売却は誘発しません。フィールドの「最新」をクリックすると「前N日」に切り替えられます (取引日を基準に遡り、最大 60 日、信号ライブラリと同じ口径)。フィールドデータが欠落している日は候補外です (拡張データが未補完の交易日など)。',
  ' matrix 策略不支持字符串字段条件。': ' matrix 戦略は文字列フィールド条件に対応していません。',
