  '对通过筛选的候选按因子加权打分排序；评分不改变是否入选，只决定排序先后。权重保存时自动归一。': 'フィルタを通過した候補をファクターの重み付けスコアで並べ替えます。スコアは採用可否ではなく順位のみに影響します。重みは保存時に自動正規化されます。',
  '{n} 个因子': 'ファクター {n} 個',
  '控制买卖时点：出入场触发器对回测与监控生效（任一命中即触发）；策略扫描不消费触发器，仍按策略自身规则。风控与持仓纪律作为策略默认值保存，回测 / 优化 / 走查打开时自动继承。': '売買タイミングを制御します。エントリー / エグゼイトリガーはバックテストと監視で有効 (いずれか一致で発火)。戦略スキャンではトリガーを参照せず、戦略自身のルールに従います。リスク管理と保有規律は戦略の初期値として保存され、バックテスト / 最適化 / ウォークフォワードを開くときに自動的に引き継がれます。',
