  '盈利交易数占已完成交易数的比例。': '完了した取引のうち、利益となった取引の割合です。',
  '胜率高不代表总收益一定高，还需结合盈亏比。': '勝率が高くても総収益が高いとは限らず、損益比との併用が必要です。',
  '平均盈利幅度 ÷ 平均亏损幅度的绝对值。': '平均利益幅 ÷ 平均損失幅の絶対値です。',
  '大于 1 表示平均单笔盈利大于平均单笔亏损。': '1 を超える場合は、平均的な勝ち取引の利益が平均的な負け取引の損失を上回ります。',
  '总收益': '総収益',
  '回测期末权益相对初始资金的累计收益率。': 'バックテスト終了時の資産残高が元本に対して達成した累積収益率です。',
  '已反映回测中的仓位、费用、滑点和成交约束。': 'バックテスト内のポジション、手数料、スリッページ、約定制約を反映済みです。',
  '将回测期总收益按复利折算为一年的收益率。': 'バックテスト期間の総収益を複利で一年換算した収益率です。',
  '短周期回测的年化结果可能被明显放大。': '短期バックテストの年率は大幅に拡大表示されることがあります。',
  '同期上证': '同期間上证',
  '同一回测区间内上证指数的累计收益率。': '同一バックテスト期間における上证指数の累積収益率です。',
  '用于判断策略表现是否主要来自市场整体涨跌。': '戦略の成果が主に市場全体の涨跌によるものかを判断するために使います。',
  '超额收益': '超過収益',
  '策略总收益率减去同期上证指数收益率。': '戦略の総収益率から同期間の上证指数の収益率を差し引いた値です。',
  '正值表示跑赢基准，负值表示跑输基准。': '正值はベンチマークを上回ったこと、負値は下回ったことを示します。',
