  '收益序列的平均收益 ÷ 总波动，并按 252 期年化。': '収益数列の平均収益 ÷ 総ボラティリティを252期で年率化した値です。',
  '数值越高，单位波动获得的收益越多；小样本时仅供参考。': '値が高いほど単位当たりのボラティリティに対する収益が大きく、サンプル数が少ない場合は参考値として扱ってください。',
  '索提诺比率 (Sortino Ratio)': 'ソルティノレシオ (Sortino Ratio)',
