  '只惩罚负收益波动，不将向上波动视为风险。': '負の収益のボラティリティのみを罰し、上振れはリスクとして扱いません。',
  '回测权益从历史高点到随后最低点的最大跌幅。': 'バックテストの資産残高が過去の高値からその後の最安値まで下落した最大幅です。',
  '越接近 0 通常代表历史资金回撤越小。': '0 に近いほど過去の資金ドローダウンが小さいことを表します。',
  '蒙卡回撤 (中位/95%)': 'モンテカルロドローダウン (中央値/95%)',
  '对交易收益有放回重抽样 1000 次, 各算最大回撤: 中位值 = 典型运气下的回撤, 95% 边界 = 偏悲观的压力边界。': '取引収益を有放回抽出で1000回リサンプリングし、各回の最大ドローダウンを算出します。中央値は運が平均的な場合のドローダウン、95%境界は悲観的なストレス境界を表します。',
  '中位值用于和实际最大回撤对照判断序列运气; 资金管理按 95% 边界准备。交易数多时两者可能同时逼近 -100%, 参考价值下降。': '中央値と実際の最大ドローダウンを対比して数列の運を判断し、資金管理は95%境界を基準にしてください。取引数が多いと双方が -100% に近づき、参考価値が低下します。',
