  '对比盈利单与亏损单入场时的因子取值：胜单均值明显高于败单 → 该因子在本轮交易里贡献了正筛选力；反之在拖后腿。原始因子量纲不同，只看相对差异。': '勝ち取引と負け取引のエントリー時のファクター値を比較します。勝ちの平均が明らかに高い場合は、そのファクターが今回の取引でプラスの選別力を加えたことを意味し、反対の場合は拖累しました。元のファクターは単位が異なるため、相対的な差のみを見てください。',
  '胜单均值': '勝ち平均',
  '败单均值': '負け平均',
  '差值(胜-败)': '差分(勝ち-負け)',
  '样本(胜/败)': 'サンプル(勝ち/負け)',
  '回测基于历史数据与当前参数设定模拟,受成交假设与市场环境影响,过往结果不代表未来收益; 行情数据来自第三方数据源,其准确性、完整性与及时性不作保证,可能存在缺失、延迟或错误; 仅供参考,不构成投资建议,请独立决策并自担风险。': 'バックテストは過去データと現在の設定でシミュレーションしたもので、約定の前提と市場環境の影響を受けます。過去の結果は将来の 収益を保証しません。相場データは第三者提供で、正確性・完全性・適時性は保証されず、欠落・遅延・誤りが含まれる可能性があります。参考情報のみであり投資助言ではないため、ご自身で判断しリスクをご承担ください。',
  '高级策略设置': '高度な戦略設定',
  '编辑的是本次回测的临时参数；「应用到策略」可持久化为策略默认值。': 'ここで編集しているのは今回のバックテスト用の一時パラメータです。「戦略に適用」で戦略のデフォルト値として保存できます。',
  '决定哪些股票进入候选：基础过滤 → 策略参数 → 叠加条件，逐层收紧；此处改动只影响本次回测，不会保存。': 'どの銘柄が候補になるかを決めます：ベースフィルタ → 戦略パラメータ → 重ね合わせ条件と段階的に絞り込みます。ここでの変更は今回のバックテストにのみ反映され、保存されません。',
  '启用基础过滤': 'ベースフィルタを有効化',
  '排除 ST / 退市': 'ST・上場廃止を除外',
  '字段与策略设置「基础参数」一致，初始值取自策略配置；清空某项即改为不限（会覆盖策略原值）。': '項目は戦略設定の「基本パラメータ」と同じで、初期値は戦略設定から取得します。空欄にすると無制限になります（戦略の元値は上書きされます）。',
  '项': '件',
  '当前策略没有可调参数。': '現在の戦略には調整できるパラメータがありません。',
  '默认继承策略设置里保存的叠加条件；字段可点「最新」切换为「前N日」（上限 60 日）。ETF 回测通常无扩展数据字段，请谨慎使用。': '既定では戦略設定に保存された重ね合わせ条件を継承します。項目」をクリックすると「最新」から「前N日」（最大60日）に切り替えられます。ETF バックテストには通常拡張データ項目がないため、慎重に利用してください。',
  'matrix 策略不支持字符串字段条件。': 'matrix 戦略は文字列項目の条件に対応していません。',
  '留空 = 不过滤；命中范围后按评分从高到低买入': '空欄＝フィルタなし。範囲に一致した後はスコアの降順で買い入れます',
  '最小评分': '最小スコア',
  '最大评分': '最大スコア',
  '例如最小值 71 表示只把评分 ≥ 71 的股票放入下一交易日买入预选池。': '例えば最小値 71 の場合、スコアが 71 以上の銘柄のみが翌取引日の買い入れ候補に入ります。',
  '触发 / 成交 / 仓位关系': 'トリガー・約定・ポジションの関係',
  '触发器决定什么时候产生买卖信号；评分只在多个买点同时出现时排序。': 'トリガーは売買シグナルの発生タイミングを決めます。スコアは複数の買いポイントが同時に出たときの並び順に使われます。',
  '成交口径可分别设置建仓/清仓：默认建仓次日开盘（避免未来函数）、清仓当日收盘（持仓中可盘中/收盘卖）。': '買い・売りの約定基準は個別に設定できます：買いは既定で翌日の寄り付き（未来関数対策）、売りは当日終値です（保有中は日中・終値どちらでも売却可能）。',
  '退出优先级：止损/移动止损 &gt; 卖点信号 &gt; 到期平仓；到期只作兜底，不抢占卖点或风控。': '決済の優先順位：損切り／トレーリングストップ &gt; 売りシグナル &gt; 期限切れ決済。期限切れはフォールバックのみで、売りシグナルやリスク管理を先取りしません。',
  '最大持仓数控制同时持股数量，最大总仓位控制资金投入比例；剩余现金不等于可新增持仓名额。': '最大保有銘柄数は同時に保有する銘柄数を、最大総ポジションは資金投入の割合を制御します。残った現金は追加の保有枠ではありません。',
  '当前为 Matrix 策略，进出场信号由策略公式生成，不能用列信号覆盖。': '現在は Matrix 戦略です。売買シグナルは戦略式で生成され、列シグナルで上書きすることはできません。',
