  '① 因子 = 给股票打分排序的特征（如 20日涨幅、换手率变化）；② 本页度量过去哪些特征与次日涨跌存在稳定关联；③ IC = 关联强度（绝对值越大越强，负值反向用），IR = 稳定度（越大越稳）。所有结果均为历史统计，不构成投资建议，不代表未来表现。': '① ファクターは株式にスコアを付けて順位付けする特徴量です（例: 20日騰落率、回転率の変化）。② このページでは、どの特徴量が翌日の騰落と安定した関連を持っていたかを計測します。③ IC は関連の強さ（絶対値が大きいほど強く、負の値は逆向きに使用）、IR は安定度（大きいほど安定）です。すべての結果は過去統計であり、投資助言ではなく、将来の成績を保証するものではありません。',
