  'Newey-West HAC 稳健 t 值（滞后 1）：|t|≥2 视为统计显著；悬停查看多重检验校正后的 q 值（≤0.1 通过）。样本不足显示 —。': 'Newey-West HAC 頑健 t 値（ラグ 1）: |t|≥2 で統計的に有意とみなします。ホバーで多重検定補正後の q 値（0.1 以下で合格）を確認できます。サンプル不足時は — を表示します。',
  '方向一致占比': '方向一致率',
  'IC 与自身方向一致的天数占比。50% 是抛硬币，55%+ 不错。': 'IC の符号が因子の向きと一致した日の割合。50% はコイン投げ、55% 以上なら良好です。',
  '多空收益': '売買差収益',
  '每期买因子最高组、（模拟）卖最低组的累计收益差。A 股做空受限，此列为理论口径。': '各期にファクター最上位グループを買い（仮想で）最下位グループを売ったときの累積収益差。A株では空売りに制限があるため、この列は理論値です。',
  '上述多空组合最痛的一段亏损幅度，衡量拿得住不住。': '上記の売買差组合で最も苦しかった損失幅。相場に耐えられるかを測ります。',
  '样本内方向：值大看多（IC 为正）。历史方向不代表未来。': '样本内方向：値が大きいと強気（IC が正）。過去の方向が未来を表すわけではありません。',
  '样本内方向：值小看多（IC 为负，反向使用）。历史方向不代表未来。': '样本内方向：値が小さいと強気（IC が負、逆向きに使用）。過去の方向が未来を表すものではありません。',
  '加入信号条件（方向按 IC 预填，阈值给建议值）': 'シグナル条件に追加（方向は IC から自動入力、閾値は推奨値）',
