  '不知道选什么因子？让系统全量筛选达标因子并自动搜索组合（嵌套样本外验证）': 'どのファクターを選べばいいか迷ったら、システムが全ファクターをスクリーニングして組み合わせを自動探索します（入れ子型アウトオブサンプル検証）',
  '左侧选因子（或用预设）→ 点「筛选」批量检验 → 点击结果行看单因子详情。 IC 衡量历史上因子值与后续涨跌的关联强度（绝对值越大关联越强），IR 是稳定度。': '左でファクターを選択（またはプリセットを使用）→「筛选」をクリックして一括検定 → 結果行をクリックして単一ファクターの詳細を確認。IC は過去のファクター値と、その後の騰落との関連の強さを測ります（絶対値が大きいほど強い）。IR は安定度です。',
