  '不用挑因子：先全量统计筛选（|t|≥2、q≤0.1、IC/IR 达标），再用达标池做相关性去重 → 组合搜索 → 嵌套样本外验证。结果里能看到哪些因子/组合达标、不达标的差在哪。': 'ファクターを手で選ぶ必要はありません。まず全量スクリーニング（|t|≥2、q≤0.1、IC/IR 达标）を行い、达标プールを相関で重複排除 → 組み合わせ探索 → 入れ子型アウトオブサンプル検証の順で進めます。結果にはどのファクター・組み合わせが达标したか、达标しなかった理由が表示されます。',
