  '竞价异动 (同花顺盘前风向标与全市场竞价扫描) 依赖 fuyao 数据源, 复盘页的龙虎榜同样来自该数据源。在「设置 → 数据源」配置 fuyao API Key 后即可使用。': '競り売り異動（同花順の盤前風向標と全市場の競り売りスキャン）は fuyao データソースに依存します。レビュー画面のゴウチュウバンも同じデータソースから取得します。「設定 → データソース」で fuyao の API Key を設定すると利用できます。',
  '前往配置数据源': 'データソース設定へ',
  '全市场竞价扫描': '全市場競り売りスキャン',
  '待采集任务启用': '収集タスクの有効化待ち',
  '9:25 竞价终态后扫描全市场 (实测 5547 只约 2 秒), 自动筛出高开 ≥5% 且竞价量比 ≥10 的标的并按日落盘积累历史。竞价明细无历史接口, 数据从采集启用之日起积累。': '9:25 の競り売り確定後に全市場をスキャンします（実測 5,547 銘柄で約 2 秒）。高値率 ≥5% かつ競り売り出来高比率 ≥10 の銘柄を自動抽出し、日次で保存して履歴を蓄積します。競り売り明細に履歴 API はないため、収集有効化以降のデータのみ蓄積されます。',
  '风向标为同花顺盘前竞价筛选名单 (每日约 5~6 只)。60 日回测: 名单当日开盘买入均值 +0.54% (超额 +0.44%), 但高开 ≥5% 子集当日 -1.97% — 追高是陷阱, 次日无显著优势, 仅作当日观察。': '風向標は同花順の盤前競り売り選別リスト（1日あたり約5～6銘柄）です。60日バックテストでは当日の寄り付き買い平均が +0.54%（超额 +0.44%）でしたが、高値率 ≥5% のサブセットは当日 -1.97% でした。追高は罠で翌日も優位性がないため、当日の観察用途に限って利用します。',
