  '口径说明: 偏离值 = 个股 N 日累计涨跌幅 − 对应指数同期涨跌幅 (沪主板: 上证A指/上证指数, 科创板: 科创50, 深主板: 深证A指/深证成指, 创业板: 创业板综指, 北: 北证50)。 阈值为交易所异常波动披露标准的近似值, 仅供风险提示, 不构成监管认定。每只股票在 3日/10日/30日 三档各算一个接近度 (|偏离值| ÷ 该档阈值, 阈值随板块不同; 2026-07-06 起主板风险警示股票与普通股票同口径), 表格「接近度」列与状态取三档中的最高值, 来源窗口的偏离值颜色加重显示、其余窗口淡化; ≥100% 已触发、≥70% 边缘、≥50% 观察。 偏离列亦可在自选/策略的「异动」列组中启用, 并可作为监控规则与自定义信号的阈值字段。': '基準: 乖離率 = 銘柄のN日累計騰落 - 対応指数の同期間騰落（上海主板: 上証A指 / 上証指数、科創板: 科創50、深圳主板: 深証A指 / 深証成指、創業板: 創業板総合、北: 北証50）。しきい値は取引所の異常変動開示基準の近似値であり、リスク喚起のための参考であって規制上の認定を構成しません。各銘柄は3日 / 10日 / 30日 の3区分それぞれに接近度（|乖離率| ÷ 該当区分のしきい値。しきい値は板により異なり、2026-07-06以降は主板のリスク警告銘柄も通常銘柄と同じ基準）を算出します。表の「接近度」列とステータスは3区分の最大値を取り、出典の区分の乖離率は色を強調して他の区分は淡色表示します。≥100% 発生済み、≥70% 境界、≥50% 監視。乖離列は自選 / 戦略の「異動」列グループでも有効化でき、監視ルールやカスタムシグナルのしきい値フィールドとして利用できます。',
  '监控未开启': '監視はOFFです',
  '开启后按交易所异动规则实时计算全市场个股的涨跌幅偏离值 (个股 N 日累计涨跌 − 对应指数同期), 找出接近触发「异常波动 / 严重异常波动」的标的。 计算量较大, 默认关闭; 每次计算的结果会保留, 关闭后仍可查看 (不再实时更新)。': '有効化すると、取引所の異動ルールに従って全市場銘柄の騰落乖離率（銘柄のN日累計騰落 − 対応指数の同期間）をリアルタイムに算出し、「異常変動 / 嚴重異常変動」の発生間近の銘柄を洗い出します。計算量が多いため既定ではOFFです。計算結果は保存されるため、OFFにした後も前回結果を確認できます（リアルタイム更新は停止します）。',
  '需要告警推送时, 在': 'アラート推送が必要な場合は「',
